import 'package:flutter/material.dart';

class SectionTitle extends StatelessWidget { final String title; final String? action; final VoidCallback? onTap; const SectionTitle(this.title, {super.key, this.action, this.onTap}); @override Widget build(BuildContext context) => Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [Text(title, style: Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight: FontWeight.bold)), if (action != null) TextButton(onPressed: onTap, child: Text(action!))]); }
 class StatusPill extends StatelessWidget { final IconData icon; final String label; final Color color; const StatusPill({super.key, required this.icon, required this.label, required this.color}); @override Widget build(BuildContext context) => Container(padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8), decoration: BoxDecoration(color: color.withValues(alpha: .1), borderRadius: BorderRadius.circular(24)), child: Row(mainAxisSize: MainAxisSize.min, children: [Icon(icon, size: 16, color: color), const SizedBox(width: 6), Text(label, style: TextStyle(color: color, fontWeight: FontWeight.w600))])); }
class EmptyState extends StatelessWidget { final IconData icon; final String title, detail; const EmptyState({super.key, required this.icon, required this.title, required this.detail}); @override Widget build(BuildContext context) => Center(child: Padding(padding: const EdgeInsets.all(32), child: Column(mainAxisSize: MainAxisSize.min, children: [Icon(icon, size: 48, color: Theme.of(context).colorScheme.primary), const SizedBox(height: 12), Text(title, style: Theme.of(context).textTheme.titleLarge), const SizedBox(height: 6), Text(detail, textAlign: TextAlign.center)]))); }
